// Regenerate the authored corpus: cd sdk && npx tsx test/fixtures/generate.ts.
// Expectations below are authored independently of the replay implementation.
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { commands as c, run } from "./build.ts";
import type { Fixture } from "./build.ts";

const dir = fileURLToPath(new URL("../../../conformance/fixtures/", import.meta.url));
function write(number: number, slug: string, description: string, fixture: Fixture): void {
  fixture.name = slug.replaceAll("-", " ");
  fixture.description = description;
  writeFileSync(`${dir}/${String(number).padStart(3, "0")}-${slug}.json`, JSON.stringify(fixture, null, 2) + "\n");
}

write(2, "parallel-out-of-order", "Calls inside Promise.all receive seq in call order, while results arrive 2 then 1 and retain input order.", run("parallelActivities").task().scheduleActivity(1, "double", 1).scheduleActivity(2, "double", 2).completeActivity(2, 4).completeActivity(1, 2).task().expectCommands(c.completeRun([2, 4])));
write(3, "failure-caught-retry", "An exhausted activity failure reaches user catch code, which schedules a distinct activity with the next seq.", run("retryInWorkflow").task().scheduleActivity(1, "double", 1).failActivity(1, "no", "Denied").task().expectCommands(c.scheduleActivity(2, "double", 2)));
write(4, "sleep-starts", "A new durable sleep emits one timer.", run("sleeping").task().expectCommands(c.startTimer(1)));
write(5, "sleep-fires", "TimerFired resumes a pending durable sleep.", run("sleeping").task().startTimer(1).fireTimer(1).task().expectCommands(c.completeRun("awake")));
write(6, "race-activity-wins", "Promise.race resolves from the activity event; a losing sleep remains pending until run closure.", run("raceActivityAndSleep").task().scheduleActivity(1, "double", 21).startTimer(2).completeActivity(1, 42).task().expectCommands(c.completeRun(42)));
write(7, "race-timer-wins", "Promise.race resolves from the timer event and preserves call-time seq allocation.", run("raceActivityAndSleep").task().scheduleActivity(1, "double", 21).startTimer(2).fireTimer(2).task().expectCommands(c.completeRun("timeout")));
write(8, "condition-already-true", "An already true condition resolves without allocating a command.", run("immediateCondition").task().expectCommands(c.completeRun(true)));
write(9, "condition-signal", "A condition without a timeout wakes after its signal handler changes the predicate.", run("signalledCondition", {}).task().signal("ready", true).task().expectCommands(c.completeRun(true)));
write(10, "condition-timeout", "A condition returns false when its durable timeout fires first.", run("signalledCondition", { timeout: "1s" }).task().startTimer(1).fireTimer(1).task().expectCommands(c.completeRun(false)));
write(11, "condition-cancels-timer", "A signal satisfying a timed condition cancels the outstanding timer by its existing seq before completing.", run("signalledCondition", { timeout: "1s" }).task().startTimer(1).signal("ready", true).task().expectCommands(c.cancelTimer(1), c.completeRun(true)));
write(12, "signal-before-registration", "A signal received before continuation registers its handler is buffered and delivered on registration.", run("bufferedHandler").task().scheduleActivity(1, "double", 1).signal("number", 7).completeActivity(1, 2).task().expectCommands(c.completeRun([7])));
write(13, "handler-history-order", "A handler receives every signal synchronously and in event history order.", run("orderedHandler").task().signal("number", 7).signal("number", 9).task().expectCommands(c.completeRun([7, 9])));
write(14, "next-signal-fifo", "nextSignal consumes buffered signals once, in arrival order, including one requested by an async continuation.", run("twoSignals").task().signal("number", 7).signal("number", 9).task().expectCommands(c.completeRun([7, 9])));
write(15, "side-effect-recorded", "Replay returns the marker details without invoking the now-throwing callback.", run("recordedSideEffect").task().marker(1, "side_effect", "", { original: 7 }).scheduleActivity(2, "double", 1).completeActivity(2, 2).task().expectCommands(c.completeRun({ original: 7 })));
write(16, "uuid-recorded", "UUID replay returns the recorded UUID and does not generate a replacement.", run("recordedUuid").task().marker(1, "uuid", "", "12345678-1234-4234-8234-123456789abc").scheduleActivity(2, "double", 1).completeActivity(2, 2).task().expectCommands(c.completeRun("12345678-1234-4234-8234-123456789abc")));
write(17, "patch-new", "A patch first reached in a new activation records true, consumes seq, and takes the new branch.", run("patchBranch").task().expectCommands(c.recordMarker(1, "patch", "v2", true), c.scheduleActivity(2, "newDouble", 21)));
write(18, "patch-old", "A patch absent from an older activation returns false and consumes no seq.", run("patchBranch").task().scheduleActivity(1, "double", 21).completeActivity(1, 42).task().expectCommands(c.completeRun(42)));
write(19, "deprecate-historical-patch", "Deprecating a patch consumes its historical patch marker and preserves later seq.", run("deprecatedPatch").task().marker(1, "patch", "v2", true).scheduleActivity(2, "newDouble", 21).completeActivity(2, 42).task().expectCommands(c.completeRun(42)));
write(20, "deprecate-new", "A newly reached deprecation emits a deprecated_patch marker before the new branch.", run("deprecatedPatch").task().expectCommands(c.recordMarker(1, "deprecated_patch", "v2", true), c.scheduleActivity(2, "newDouble", 21)));
