write(21, "random-stable", "For run id conformance, random hashes conformance/0/0 then conformance/1/1 with FNV-1a; random itself consumes no seq.", run("stableRandom").task().scheduleActivity(1, "double", 1).completeActivity(1, 2).task().expectCommands(c.completeRun([0.8772211656905711, 0.39345599384978414])));
write(22, "activation-time", "now is the processed TaskStarted time, both before and after the awaited activity.", run("activationTime").task("2026-09-28T12:00:01Z").scheduleActivity(1, "double", 1).completeActivity(1, 2).task("2026-09-28T13:00:00Z").expectCommands(c.completeRun([1790596801000, 1790600400000])));
