write(27, "stray-fired-after-cancel", "TimerFired after matching TimerCancelled is ignored, while later signals still resume the workflow.", run("conditionThenSignal").task().startTimer(1).signal("ready", true).task().cancelTimer(1).fireTimer(1).signal("done", "finished").task().expectCommands(c.completeRun("finished")));
