write(41, "activity-timeout", "An activity timeout reaches workflow code as TimeoutFailure with the wire timeout type.", run("observeActivityFailure").task().scheduleActivity(1, "double", 1).external("activityTimedOut", { seq: "1", scheduledEventId: "5", timeoutType: "TIMEOUT_TYPE_HEARTBEAT", attempt: 3 }).task().expectCommands(c.completeRun({ type: "TimeoutFailure", timeoutType: "HEARTBEAT" })));
