write(44, "nested-promise-drain", "Nested async functions and Promise.all must fully drain after an activity result before the runtime returns.", run("nestedContinuations").task().scheduleActivity(1, "double", 21).completeActivity(1, 42).task().expectCommands(c.completeRun(86)));
